// Meta instant form → Edgehomes /api/lead payload. Handles simplified and raw trigger output.
return $input.all().map(item => {
  const j = item.json;
  const f = {};
  if (Array.isArray(j.field_data)) j.field_data.forEach(x => { f[x.name] = (x.values || [])[0]; });
  Object.assign(f, j.data || {}, j.fields || {});
  const pick = (...keys) => { for (const k of keys) if (f[k] != null && f[k] !== '') return f[k]; return ''; };
  return { json: {
    name: pick('full_name', 'name', 'first_name'),
    phone: pick('phone_number', 'phone', 'mobile'),
    email: pick('email'),
    city: pick('city', 'which_city_is_your_home_in?', 'city_name'),
    society: pick('society', 'which_society_or_sector?', 'society_name'),
    property: pick('property', 'home_type', 'what_are_we_designing?'),
    possession: pick('possession', 'when_is_your_possession?', 'possession_month'),
    budget: pick('budget', 'rough_budget?', 'interior_budget'),
    source: 'meta_form',
    campaign: (j.campaign && j.campaign.name) || j.campaign_name || '',
    adset: (j.adset && j.adset.name) || j.adset_name || '',
    ad: (j.ad && j.ad.name) || j.ad_name || '',
    form_name: (j.form && j.form.name) || j.form_name || '',
    // Meta instant forms used for Edgehomes MUST include the WhatsApp consent checkbox (see brief §6)
    consent: !!(f.whatsapp_consent || f.consent || j.consent),
    consent_source: 'Meta instant form consent checkbox',
  } };
});

